+		plus, minus         bool
+		wantPlus, wantMinus int
+	}{
+		{true, false, 1, 0},
+		{false, true, 0, 1},
+		{true, true, 1, 1},
+		{false, false, 0, 0},
+	} {
+		results, err := diff(current, previous, tc.plus, tc.minus)
+		if err != nil {
+			t.Fatal(err)
+		}
